mapper.select:
SELECT task_id, trace_id, tenant_id, run_id, source, priority, status, assigned_to, root_cause, created_at FROM platform.review_task
AND status = #{status}
AND status IN ('PENDING', 'IN_REVIEW')
AND tenant_id = #{tenantId}::uuid
ORDER BY CASE priority WHEN 'HIGH' THEN 0 WHEN 'NORMAL' THEN 1 ELSE 2 END, created_at ASC LIMIT #{limit}
